CURRENCY_SYMBOLS = {"EUR": "\u20ac", "USD": "$", "GBP": "\u00a3"}


def format_amount(amount, currency):
    """Format a ``Decimal`` amount with the currency's prefix symbol."""
    return "{}{:.2f}".format(CURRENCY_SYMBOLS[currency], amount)


